tool_info.command_line:
node --input-type=module - <<'EOF'
import { chromium } from 'playwright';
import path from 'node:path';
const zipPath = path.resolve('/workspaces/semio/compose/assets/compose/metabolism.zip');

async function scenario(kind){
  const browser = await chromium.launch({headless:true});
  const page = await browser.newPage();
  const errs=[];
  page.on('console',m=>{ if(m.type()==='error') errs.push(m.text()); });
  page.on('pageerror',e=>errs.push('[pageerror] '+e.message));
  await page.goto('http://127.0.0.1:5173/', {waitUntil:'domcontentloaded'});
  await page.waitForTimeout(1500);
  const input = page.locator('[id="compose.sketchpad.app.home.importKit"]');
  console.log('\nScenario', kind, 'input attached', await input.count());
  if(kind==='chooser'){
    const chooser = await Promise.all([
      page.waitForEvent('filechooser',{timeout:5000}).catch(()=>null),
      input.dispatchEvent('click')
    ]).then(([c])=>c);
    console.log('chooser?',!!chooser);
    if(chooser) await chooser.setFiles(zipPath);
  } else {
    await input.setInputFiles(zipPath);
    await input.evaluate((el)=>el.dispatchEvent(new Event('change',{bubbles:true})));
  }
  await page.waitForTimeout(4000);
  const state = await page.evaluate(() => {
    const store = window.__COMPOSE_STORE__;
    const kitGuids = store ? Array.from(store.kits.keys()) : [];
    const names = store ? kitGuids.map((g)=>store.kit(g).snapshot().name) : [];
    return {
      bodyHasMetabolism: document.body.innerText.includes('Metabolism'),
      kitCount: kitGuids.length,
      names,
      inputFilesLength: document.querySelector('#compose\\.sketchpad\\.app\\.home\\.importKit')?.files?.length ?? -1,
    };
  });
  console.log(state);
  console.log('errs', errs.slice(0,5));
  await browser.close();
}

await scenario('chooser');
await scenario('setInputFiles');
EOF

