    return {
      second: Date.now(),
      names,
      bodyHasMetabolism: document.body.innerText.includes('Metabolism'),
      bgOps: (window.__COMPOSE_ACTOR__?.getSnapshot?.()?.context?.backgroundOperations ?? []).length,
    };
  });
  console.log('[state]', i + 1, JSON.stringify(state));
}
await browser.close();
EOF

