node --input-type=module - <<'EOF'
import { chromium } from 'playwright';
import path from 'node:path';
const zipPath = path.resolve('/workspaces/semio/compose/assets/compose/metabolism.zip');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
await page.goto('http://127.0.0.1:5173/', { waitUntil: 'domcontentloaded' });
await page.waitForTimeout(1200);
const fileInput = page.locator('[id="compose.sketchpad.app.home.importKit"]');
await fileInput.setInputFiles(zipPath);
await fileInput.evaluate((el) => el.dispatchEvent(new Event('change', { bubbles: true })));
await page.getByText('Metabolism', { exact: true }).first().waitFor({ state: 'visible', timeout: 60000 });
const tableRow = page.locator('tr[data-row-id]').filter({ hasText: 'Metabolism' }).first();
if (await tableRow.isVisible().catch(()=>false)) await tableRow.dblclick({ force: true });
else await page.getByText('Metabolism', { exact: true }).first().dblclick({ force: true });
await page.waitForURL(/.*kits\/.+/, { timeout: 60000 });
await page.waitForLoadState('networkidle');
await page.waitForTimeout(1500);
const state = await page.evaluate(() => ({
  url: location.pathname,
  bodyTextLen: document.body.innerText.length,
  hasTbody: !!document.querySelector('tbody'),
  rowCount: document.querySelectorAll('[data-row-id]').length,
  composeIds: Array.from(document.querySelectorAll('[id]')).map(e=>e.id).filter(id=>id.startsWith('compose.sketchpad')).slice(0,80),
}));
console.log(JSON.stringify(state, null, 2));
await browser.close();
EOF

